USE aer_synapse_db;

DECLARE @RunDate NVARCHAR(10) = CONVERT(NVARCHAR(10), GETDATE(), 120);
DECLARE @RunDateClean NVARCHAR(8) = REPLACE(@RunDate, '-', '');
DECLARE @RunStamp NVARCHAR(25) = @RunDateClean + '_' + REPLACE(CONVERT(NVARCHAR(8), GETDATE(), 108), ':', '');

-- Drop if re-running (metadata only; location is unique per run so no physical conflict)
DECLARE @DropSQL NVARCHAR(MAX) = N'
    IF OBJECT_ID(''dbo.fact_oilprice_' + @RunStamp + N''') IS NOT NULL
        DROP EXTERNAL TABLE dbo.fact_oilprice_' + @RunStamp + N';';
EXEC sp_executesql @DropSQL;

-- CETAS: Bronze EIA Parquet -> Gold OilPrice Parquet (unique run folder, avoids ADLS empty-folder-marker conflicts)
DECLARE @SQL NVARCHAR(MAX) = N'
CREATE EXTERNAL TABLE dbo.fact_oilprice_' + @RunStamp + N'
WITH (
    LOCATION = ''/gold/fact_oilprice/' + @RunDate + N'/run_' + @RunStamp + N'/'',
    DATA_SOURCE = aer_adls,
    FILE_FORMAT = parquet_format
) AS
SELECT 
    TRY_CAST([period] AS DATE) AS PriceDate,
    TRY_CAST([value] AS DECIMAL(10,2)) AS OilPrice_USD,
    [series-description] AS SeriesDescription,
    GETDATE() AS Loaded_At
FROM OPENROWSET(
    BULK ''/bronze/oilprice/' + @RunDate + N'/*.parquet'',
    DATA_SOURCE = ''aer_adls'',
    FORMAT = ''PARQUET''
) AS b
WHERE [period] IS NOT NULL 
  AND [value] IS NOT NULL
  AND TRY_CAST([value] AS DECIMAL(10,2)) IS NOT NULL;';
EXEC sp_executesql @SQL;

